/// <summary>
/// CB627_TMSEngineProcessingTOCreation
/// Class to proceede with the creation process for TMS engine
/// </summary>
[METTMSEngineExecutionModeAttribute(METTMSEngineExecutionMode::TransferOrderCreation)]
internal final class METTMSEngineTransferOrderProccess_Creation extends METTMSEngineOrderProccess
{    
    METInventTransferTableExt metInventTransferTable;

}

Method.Source:
/// <summary>
/// New method
/// </summary>
/// <param name = "_transferTable">InventTransferTable record</param>
public void new(METTMSSourceRecordHeaderMap _sourceRecord)
{
    metInventTransferTable = _sourceRecord.getExtensionTable();
    this.init(_sourceRecord);
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public METStagingLaneId getStagingLaneId()
{
    METStagingLaneId ret = metInventTransferTable.StagingLane;

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
protected METRouteIdentifier getRouteIdentifier()
{
    METRouteIdentifier ret = metInventTransferTable.RouteIdentifier;

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
protected METRouteStopIdentifier getRouteStopIdentifier()
{
    METRouteStopIdentifier ret = metInventTransferTable.RouteStopIdentifier;

    return ret;
}

/// <summary>
/// error message
/// </summary>
/// <returns>error txt</returns>
protected ErrorTxt errorMessage()
{
    return strFmt("@MET:TMSEngineTransferOrderProcessCreation", sourceRecord.OrderId);
}
